previewCss:
.darma-loader-darma-b9-heartbeat { --accent: var(--loader-color, #e11d48); --accent-2: var(--loader-secondary-color, #fb7185); width: var(--loader-size, 72px); height: var(--loader-size, 72px); position: relative; animation: darma-loader-darma-b9-heartbeat-beat calc(var(--loader-speed, 1s) * 1.2) ease-in-out infinite; }
.darma-loader-darma-b9-heartbeat span { position: absolute; top: 32%; left: 50%; width: 42%; height: 42%; transform: translateX(-50%) rotate(-45deg); background: linear-gradient(45deg, var(--accent-2), var(--accent)); box-shadow: 0 0 calc(var(--loader-size, 72px) * .18) color-mix(in srgb, var(--accent) 55%, transparent); }
.darma-loader-darma-b9-heartbeat span::before, .darma-loader-darma-b9-heartbeat span::after { content: ''; position: absolute; width: 100%; height: 100%; border-radius: 50%; background: inherit; }
.darma-loader-darma-b9-heartbeat span::before { top: -50%; left: 0; }
.darma-loader-darma-b9-heartbeat span::after { top: 0; left: 50%; }
@keyframes darma-loader-darma-b9-heartbeat-beat { 0%, 100% { transform: scale(.82); } 15% { transform: scale(1.05); } 30% { transform: scale(.9); } 45% { transform: scale(1); } 60% { transform: scale(.82); } }

